 * Designed for reliability dashboards grouped by model/source/error-class.
 */
export type JobErrorClass =
  | "none"              // completed successfully
  | "infra"             // spawn_error, timeout, runner_failed — environment/process failures
  | "parse"             // invalid_json, empty_output — worker produced unusable output
  | "schema"            // invalid_structured_output — output parsed but didn't match schema
  | "worker"            // command_failed — worker ran but reported failure
  | "input";            // invalid_input — bad job spec before execution

export function classifyJobError(status: OrchestrationJobStatus): JobErrorClass {
  switch (status) {
    case "completed":
      return "none";
    case "spawn_error":
    case "timeout":
    case "runner_failed":
      return "infra";
    case "invalid_json":
    case "empty_output":
      return "parse";
    case "invalid_structured_output":
      return "schema";
    case "command_failed":
      return "worker";
    case "invalid_input":
      return "input";
  }
}
```

